1	// Removes duplicate users. Two users are "the same" if they have the same email
2	// (comparison should be case-insensitive and ignore surrounding whitespace).
3	function dedupeUsers(users) {
4	  const seen = new Set();
5	  const out = [];
6	  for (const u of users) {
7	    // BUG: dedupes by id, not by normalized email
8	    if (!seen.has(u.id)) {
9	      seen.add(u.id);
10	      out.push(u);
11	    }
12	  }
13	  return out;
14	}
15	
16	module.exports = { dedupeUsers };
